WITH base AS (SELECT id, order_id, paid_at, status, TRIM(method) AS clean_method, COALESCE(method, 'NONE') AS resolved_method FROM payments WHERE paid_at >= TIMESTAMP '2023-07-25 15:00:00') SELECT id, paid_at, status, resolved_method, ROW_NUMBER() OVER w_grp AS seq_no, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY paid_at, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY order_id, status ORDER BY paid_at, id) AS seq_no_2 FROM base WHERE order_id IS NOT NULL WINDOW w_grp AS (PARTITION BY order_id, status ORDER BY paid_at DESC, id);
